const raw = $input.first().json || {};
if (raw.body) {
  const expected = $env.N8N_CALENDAR_TOKEN;
  const auth = raw.headers?.authorization || raw.headers?.Authorization || '';
  if (!expected || auth !== `Bearer ${expected}`) throw new Error('AUTH_FAILED: agenda local requiere bearer valido del VPS.');
}
const inp = raw.body || raw;
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const fecha = String(inp.fecha || '').trim() || hoy;
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) throw new Error('FECHA_INVALIDA: usa YYYY-MM-DD, recibi ' + fecha);
const horaInicio = Number(inp.hora_inicio ?? 9);
const horaFin = Number(inp.hora_fin ?? 18);
const duracion = Number(inp.duracion_minutos ?? 60);
if (!Number.isInteger(horaInicio) || !Number.isInteger(horaFin) || horaInicio < 0 || horaFin > 24 || horaFin <= horaInicio) throw new Error('HORARIO_INVALIDO: hora_inicio y hora_fin deben delimitar una ventana valida.');
if (!Number.isInteger(duracion) || duracion < 5 || duracion > 480) throw new Error('DURACION_INVALIDA: usa minutos enteros entre 5 y 480.');
return [{ json: { date: fecha, workStartHour: horaInicio, workEndHour: horaFin, slotMinutes: duracion } }];

const meta = $('Preparar Consulta').first().json;
const raw = $input.first() ? ($input.first().json || {}) : {};
if (raw.ok !== true) throw new Error('DISPONIBILIDAD_NO_VERIFICABLE: Calendar no devolvio un contrato ok; no asumas que el dia esta libre.');
const slots = Array.isArray(raw.slots) ? raw.slots : [];
const busyRaw = Array.isArray(raw.busy) ? raw.busy : [];
const tz = 'America/Mexico_City';
function hhmm(iso) { return new Intl.DateTimeFormat('es-MX', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(iso)); }
const libres = slots.map((s) => ({ inicio: s.start, fin: s.end, etiqueta: hhmm(s.start) + '-' + hhmm(s.end) }));
const ocupado = busyRaw.map((b) => hhmm(b.start) + '-' + hhmm(b.end));
const diaLibre = busyRaw.length === 0;
const ventana = meta.workStartHour + ':00-' + meta.workEndHour + ':00';
let resumen;
if (diaLibre) resumen = 'El ' + meta.date + ' no tiene eventos que bloqueen la agenda dentro de ' + ventana + ' (hora del centro de Mexico).';
else if (libres.length === 0) resumen = 'El ' + meta.date + ' no queda ningun hueco de ' + meta.slotMinutes + ' minutos dentro de ' + ventana + '.';
else resumen = 'Huecos de ' + meta.slotMinutes + ' minutos libres el ' + meta.date + ' (hora del centro de Mexico): ' + libres.map((l) => l.etiqueta).join(', ') + '.';
return [{ json: { ok: true, fecha: meta.date, dia_libre: diaLibre, duracion_minutos: meta.slotMinutes, horario_laboral: ventana, libres, ocupado, resumen } }];
